mapper.select:
select ac.problem_id, p.title, p.difficulty difficulty, ac.create_time acTime from problem p left join user_problem_ac ac on p.id = ac.problem_id where p.status = 1 and ac.user_id = #{userId}
and p.difficulty = #{difficulty}
order by ac.create_time desc

select id, title, difficulty, tag, accepted_count, submit_count, status, solution_count, (case when submit_count > 0 then round(accepted_count / submit_count * 100, 1) else 0.0 end) as pass_rate from problem
difficulty = #{difficulty}
and title like concat('%', #{keyword}, '%')
and tag like concat('%', #{tag}, '%')
and status = #{status}
order by solution_count desc order by pass_rate desc order by id asc
